// Install grommet and styled-components (or use in CodeSandbox)
import React from 'react';
import ReactDOM from 'react-dom';
import { Grommet, DataChart } from 'grommet';

const data = [
  { date: '2022-07-01', value: 10 },
  { date: '2022-07-02', value: -5 },  // negative value triggers the bug
  { date: '2022-07-03', value: 15 }
];

const App = () => (
  <Grommet>
    <DataChart
      data={data}
      series={[
        { property: 'date', render: datum => datum.date },
        'value'
      ]}
      chart={[
        {
          property: 'value',
          type: 'bar',        // bar chart type
          color: 'brand'
        }
      ]}
      axis={{ x: { property: 'date', granularity: 'day' }, y: true }}
      guide={{ y: { zero: true } }}
      size={{ width: 'medium', height: 'small' }}
    />
  </Grommet>
);

ReactDOM.render(<App />, document.getElementById('root'));
